function Grain() {
  return (
    <div style={{
      position: "fixed", inset: 0, pointerEvents: "none", zIndex: 100, opacity: 0.035,
      backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E")`,
      backgroundRepeat: "repeat",
      backgroundSize: "128px 128px",
    }} />
  );
}

function FloatingOrbs() {
  return (
    <div style={{ position: "fixed", inset: 0, pointerEvents: "none", zIndex: 0, overflow: "hidden" }}>
      <div style={{
        position: "absolute", width: 600, height: 600, borderRadius: "50%",
        background: "radial-gradient(circle, rgba(107,63,160,0.12) 0%, transparent 70%)",
        top: -200, right: -150, animation: "orbFloat 18s ease-in-out infinite",
      }} />
      <div style={{
        position: "absolute", width: 400, height: 400, borderRadius: "50%",
        background: "radial-gradient(circle, rgba(155,35,53,0.10) 0%, transparent 70%)",
        bottom: "20%", left: -100, animation: "orbFloat 24s ease-in-out infinite reverse",
      }} />
      <div style={{
        position: "absolute", width: 300, height: 300, borderRadius: "50%",
        background: "radial-gradient(circle, rgba(26,74,107,0.10) 0%, transparent 70%)",
        bottom: "5%", right: "15%", animation: "orbFloat 20s ease-in-out infinite 4s",
      }} />
    </div>
  );
}

function Nav({ active, setActive }) {
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const h = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", h);
    return () => window.removeEventListener("scroll", h);
  }, []);

  return (
    <nav style={{
      position: "fixed", top: 0, left: 0, right: 0, zIndex: 50,
      padding: "1rem 2rem",
      background: scrolled ? "rgba(8,6,14,0.88)" : "transparent",
      backdropFilter: scrolled ? "blur(20px)" : "none",
      borderBottom: scrolled ? "0.5px solid rgba(255,255,255,0.06)" : "none",
      transition: "all 0.4s ease",
      display: "flex", alignItems: "center", justifyContent: "space-between",
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <div style={{
          width: 42, height: 42, borderRadius: "50%", overflow: "hidden", flexShrink: 0,
          border: "1.5px solid rgba(180,120,255,0.6)",
          boxShadow: "0 0 14px rgba(155,80,255,0.5), inset 0 0 8px rgba(80,0,120,0.3)",
          background: "#0d0a18",
        }}>
          <img src={MASCOT} alt="Eye Yee mascot" style={{
            width: "100%", height: "100%",
            objectFit: "cover",
            objectPosition: "center 20%",
          }} />
        </div>
        <div style={{ fontFamily: "'Cinzel', serif", fontSize: 20, color: "#e8e0f0", letterSpacing: "0.12em" }}>
          EYE YEE
        </div>
      </div>
      <div style={{ display: "flex", gap: "2rem" }}>
        {NAV_ITEMS.map(item => (
          <button key={item} onClick={() => setActive(item)} style={{
            background: "none", border: "none", cursor: "pointer",
            fontFamily: "'Crimson Pro', serif", fontSize: 15,
            color: active === item ? "#c8a8e8" : "rgba(200,180,220,0.55)",
            letterSpacing: "0.06em", transition: "color 0.2s",
            borderBottom: active === item ? "0.5px solid #c8a8e8" : "0.5px solid transparent",
            paddingBottom: 2,
          }}>
            {NAV_LABELS[item]}
          </button>
        ))}
      </div>
    </nav>
  );
}

