function PortfolioSection() {
  const [filter, setFilter] = useState("All");
  const [lightbox, setLightbox] = useState(null);
  const types = ["All", "Illustration", "Chibi", "Character Design"];
  const filtered = filter === "All" ? ALL_PORTFOLIO : ALL_PORTFOLIO.filter(p => p.type === filter);

  return (
    <section style={{ padding: "6rem 2rem", maxWidth: 1100, margin: "0 auto", position: "relative", zIndex: 1 }}>
      <SectionHeader title="Portfolio" sub="ผลงานที่ผ่านมา" />
      <div style={{ display: "flex", gap: "0.75rem", justifyContent: "center", marginBottom: "3rem", flexWrap: "wrap" }}>
        {types.map(t => (
          <button key={t} onClick={() => setFilter(t)} style={{
            padding: "7px 20px", background: filter === t ? "rgba(107,63,160,0.4)" : "transparent",
            border: filter === t ? "0.5px solid rgba(155,100,220,0.6)" : "0.5px solid rgba(200,180,220,0.2)",
            borderRadius: 2, cursor: "pointer",
            fontFamily: "'Crimson Pro', serif", fontSize: 15, letterSpacing: "0.06em",
            color: filter === t ? "#d4b8f0" : "rgba(200,180,220,0.45)",
            transition: "all 0.25s",
          }}>
            {t}
          </button>
        ))}
      </div>
      <div style={{
        display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))", gap: "1.25rem",
      }}>
        {filtered.map((p, i) => (
          <PortfolioCard key={p.id} item={p} delay={i * 60} onClick={() => setLightbox(p)} />
        ))}
      </div>
      {lightbox && <Lightbox item={lightbox} onClose={() => setLightbox(null)} />}
    </section>
  );
}

function PortfolioCard({ item, delay, onClick }) {
  const [hovered, setHovered] = useState(false);
  return (
    <div
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onClick={onClick}
      style={{
        background: "rgba(255,255,255,0.02)",
        border: `0.5px solid ${hovered ? "rgba(155,100,220,0.5)" : "rgba(200,180,220,0.1)"}`,
        borderRadius: 4, overflow: "hidden", cursor: "pointer",
        transition: "all 0.35s cubic-bezier(0.22,1,0.36,1)",
        transform: hovered ? "translateY(-4px)" : "translateY(0)",
      }}
    >
      <div style={{
        height: 260, overflow: "hidden", position: "relative", background: "rgba(8,6,14,0.8)",
      }}>
        <img src={item.src} alt={item.title} style={{
          width: "100%", height: "100%", objectFit: "cover",
          objectPosition: "top center",
          transition: "transform 0.4s ease",
          transform: hovered ? "scale(1.06)" : "scale(1)",
        }} />
        <div style={{
          position: "absolute", inset: 0,
          background: hovered ? "rgba(8,6,14,0.25)" : "transparent",
          transition: "background 0.3s",
          display: "flex", alignItems: "center", justifyContent: "center",
        }}>
          {hovered && <span style={{ fontSize: 28, color: "rgba(255,255,255,0.7)" }}>⊕</span>}
        </div>
      </div>
      <div style={{ padding: "0.65rem 1.1rem" }}>
        <div style={{
          fontFamily: "'Crimson Pro', serif", fontSize: 13, color: "rgba(200,180,220,0.5)",
          letterSpacing: "0.08em",
        }}>{item.type}</div>
      </div>
    </div>
  );
}

function Lightbox({ item, onClose }) {
  useEffect(() => {
    const handler = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [onClose]);
  return (
    <div onClick={onClose} style={{
      position: "fixed", inset: 0, zIndex: 200,
      background: "rgba(4,3,8,0.92)", display: "flex",
      alignItems: "center", justifyContent: "center", padding: "2rem",
    }}>
      <div onClick={e => e.stopPropagation()} style={{ maxWidth: 800, maxHeight: "90vh", position: "relative" }}>
        <img src={item.src} alt={item.title} style={{ maxWidth: "100%", maxHeight: "80vh", objectFit: "contain", borderRadius: 4 }} />
        <div style={{
          textAlign: "center", marginTop: "1rem",
          fontFamily: "'Cinzel', serif", fontSize: 14, color: "rgba(200,180,220,0.6)", letterSpacing: "0.1em",
        }}>{item.title} · {item.type}</div>
        <button onClick={onClose} style={{
          position: "absolute", top: -12, right: -12,
          background: "rgba(200,180,220,0.12)", border: "0.5px solid rgba(200,180,220,0.2)",
          borderRadius: "50%", width: 32, height: 32, cursor: "pointer",
          color: "#e8e0f0", fontSize: 16, lineHeight: "32px", textAlign: "center",
        }}>✕</button>
      </div>
    </div>
  );
}

